// Reuse the cached OpenSky JWT if it's still valid; only hit the auth
// endpoint when it's missing or about to expire (60s safety margin).
const cfg = $('Config (edit per location)').first().json;
const staticData = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);
const SAFETY_MARGIN = 60;

if (staticData.openskyToken && staticData.openskyTokenExpiry && now < staticData.openskyTokenExpiry - SAFETY_MARGIN) {
  return [{ json: { access_token: staticData.openskyToken } }];
}

const bodyParams = Object.entries({
  grant_type: 'client_credentials',
  client_id: cfg.OPENSKY_CLIENT_ID,
  client_secret: cfg.OPENSKY_CLIENT_SECRET
}).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://auth.opensky-network.org/auth/realms/opensky-network/protocol/openid-connect/token',
  body: bodyParams,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
});

staticData.openskyToken = response.access_token;
staticData.openskyTokenExpiry = now + (response.expires_in || 1800);

return [{ json: { access_token: response.access_token } }];

// Find the aircraft to show this cycle, using the union of OpenSky's and
// FlightRadar24's live position feeds -- each draws from overlapping but not
// identical ADS-B ground-receiver networks, so combining them catches aircraft
// one network's receivers missed but the other's caught. De-duplicated by icao24
// (FR24 reports it uppercase, OpenSky lowercase); OpenSky's entry wins on overlap
// since it's the sanctioned, documented source, FR24's unofficial feed only fills
// in gaps.
//
// "To show this cycle" is deliberately not just "closest": see the rotation
// logic at the bottom -- when multiple aircraft are within ROTATION_RADIUS_KM
// (genuinely overhead, not just inside RADIUS_DEG's much wider bounding-box
// search), each cycle advances to the next one by distance instead of always
// locking onto whichever is nearest, so a second (or third) aircraft overhead
// isn't invisible for as long as the first stays in range.
const cfg = $('Config (edit per location)').first().json;
const openskyStates = $('Fetch Nearby States').first().json.states || [];
const fr24Data = $('Fetch Nearby States (FR24)').first().json;

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Unit conversions -- OpenSky reports velocity/vertical_rate in SI units
// (m/s); FR24's unofficial feed already reports both in the units a pilot
// or plane-spotter actually uses (knots, ft/min -- confirmed against a live
// sample while building this), so only the OpenSky side needs converting.
const MS_TO_KT = 1.943844;
const MS_TO_FPM = 196.850394;

const byKey = new Map();

for (const s of openskyStates) {
  if (s[5] == null || s[6] == null || !s[1] || !s[1].trim() || s[8] !== false) continue;
  const icao24 = (s[0] || '').toLowerCase();
  const callsign = s[1].trim();
  const key = icao24 || `callsign:${callsign}`;
  byKey.set(key, {
    key, callsign, lon: s[5], lat: s[6], altitude: s[7], source: 'opensky',
    icao24: icao24 || null, tail: null,
    speedKt: s[9] != null ? Math.round(s[9] * MS_TO_KT) : null,
    verticalRateFpm: s[11] != null ? Math.round(s[11] * MS_TO_FPM) : null,
  });
}

// Registration (tail number) by icao24, collected from FR24 regardless of which
// feed ends up winning "nearest" for that aircraft -- registration is static per
// airframe, so an FR24-sourced tail is still correct for an OpenSky-sourced position.
const fr24InfoByIcao24 = new Map();

if (fr24Data && !fr24Data.error && typeof fr24Data === 'object') {
  for (const info of Object.values(fr24Data)) {
    if (!Array.isArray(info)) continue; // skip "full_count"/"version"/"stats" keys
    const callsign = (info[16] || '').trim();
    const icao24 = (info[0] || '').toLowerCase();
    if (icao24 && (info[9] || info[8])) fr24InfoByIcao24.set(icao24, { registration: info[9] || null, type: info[8] || null });
    // FR24 encodes on_ground as 0/1 (a number), not a real boolean like OpenSky's
    // on_ground field -- `=== true` never matched, letting parked/grounded aircraft
    // (e.g. N512DN sitting at Seletar/QPG) through and dominating "nearest" for as
    // long as FR24 kept reporting them (maxage=14400 = up to 4 hours).
    if (!callsign || info[1] == null || info[2] == null || info[14]) continue;
    const key = icao24 || `callsign:${callsign}`;
    if (!byKey.has(key)) {
      byKey.set(key, {
        key, callsign, lon: info[2], lat: info[1], altitude: info[4], source: 'fr24',
        icao24: icao24 || null, tail: info[9] || null,
        speedKt: info[5] != null ? Math.round(info[5]) : null,
        verticalRateFpm: info[15] != null ? Math.round(info[15]) : null,
      });
    }
  }
}

const candidates = Array.from(byKey.values())
  .map(c => ({ ...c, distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, c.lat, c.lon) }))
  .sort((a, b) => a.distanceKm - b.distanceKm);

if (candidates.length === 0) {
  return [{ json: { found: false } }];
}

// Rotation only happens among aircraft that are genuinely close, not
// everything RADIUS_DEG's bounding-box search turned up -- that box is
// ~16km half-width (up to ~23km at the corners) and near a busy airport
// routinely holds 5-15 aircraft, most of which aren't meaningfully
// "overhead" in the way this project is framed. Without this filter,
// rotation would cycle through all of them and dilute how often a
// genuinely-close aircraft gets shown to 1/N.
const ROTATION_RADIUS_KM = 8;
const rotationPool = candidates.filter(c => c.distanceKm <= ROTATION_RADIUS_KM);
// Nothing within that tighter radius -- fall back to just the single
// closest candidate from the full box (pre-rotation behavior), so a quiet
// period still shows *something* plausible rather than nothing, and
// definitely not something 20km away just to satisfy "rotate to the next".
const pool = rotationPool.length > 0 ? rotationPool : candidates.slice(0, 1);

// Persisted across executions via n8n's workflow static data (the same
// mechanism $getWorkflowStaticData always refers to -- scoped to this
// workflow, survives between scheduled runs; only written back for
// trigger-driven runs on an active workflow, not manual "Execute
// Workflow" test runs). Advances to the next-by-distance candidate
// *within the current pool* from whichever key was shown last cycle; if
// that aircraft isn't in this cycle's pool (left range, or the pool
// itself changed because nothing was within ROTATION_RADIUS_KM last
// time), restarts at the pool's closest entry rather than erroring or
// guessing.
const staticData = $getWorkflowStaticData('global');
let winnerIndex = 0;
if (staticData.lastShownKey) {
  const prevIndex = pool.findIndex(c => c.key === staticData.lastShownKey);
  if (prevIndex >= 0) winnerIndex = (prevIndex + 1) % pool.length;
}

const winner = pool[winnerIndex];
staticData.lastShownKey = winner.key;
const fr24Info = winner.icao24 ? fr24InfoByIcao24.get(winner.icao24) : null;
winner.tail = winner.tail || (fr24Info && fr24Info.registration) || null;
// Static per-airframe like registration -- adsbdb's /v0/aircraft/{icao24} lookup
// (keyed by this same hex) is the richer source (full manufacturer name + ICAO
// type), but doesn't have every hex (private/GA, newly registered, or a hex
// reassigned since adsbdb's table was last refreshed). FR24's live feed carries
// a bare type code for anything it's currently tracking, so Build Payload
// (Matrix64) falls back to this when adsbdb comes up empty.
winner.fr24AircraftType = (fr24Info && fr24Info.type) || null;

return [{ json: { found: true, ...winner } }];

// TC002 has no icon storage -- every push embeds the icon's pixels inline as
// base64 (16x16, from the airline_icons data table).
const nearest = $('Nearest Aircraft').first().json;
const cmp = $('Compare Routes').first().json;

if (cmp.skip) {
  return [];
}

const callsignText = cmp.callsignIata || nearest.callsign;
const routeText = cmp.trustedRoute ? `${cmp.trustedRoute.from}-${cmp.trustedRoute.to}` : null;
// Logo rows from Lookup Icon (airline_icons data table), which fetches the
// ICAO match, the IATA match and the generic '00' row in one query. The ICAO
// designator wins, then adsbdb's IATA code, then '00'.
const iconRows = $('Lookup Icon').all().map(i => i.json);
const iconRow = (cmp.airlineIcao && iconRows.find(r => r.icao === cmp.airlineIcao))
  || (cmp.airlineIata && iconRows.find(r => r.iata === cmp.airlineIata))
  || iconRows.find(r => r.code === '00');
const iconB64 = iconRow && iconRow.icon16;
const text = [
  { content: callsignText, fontHeight: 5, x: 20, y: 1, color: '#FFFFFF' }
];
if (routeText) {
  text.push({ content: routeText, fontHeight: 5, x: 20, y: 9, color: '#3EE08A' });
}

const payload = { duration: 10, text };
if (iconB64) {
  payload.image = [{ data: `data:image/gif;base64,${iconB64}`, position: [0, 0] }];
}

return [{ json: payload }];

const nearest = $('Nearest Aircraft').first().json;
const resp = $('Lookup Route (adsbdb)').first().json;
const fr24 = $('Verify Route (FR24)').first().json;

function distanceKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// FlightRadar24's live feed (unofficial data-cloud.flightradar24.com/zones/fcgi/feed.js
// endpoint) reflects what's actually airborne right now, unlike adsbdb/hexdb.io's static
// flight-number tables, which can hold decade-old records (TGW543/TR543 resolved to a
// stale 2012 SYD-MEL entry in both). It also carries private/GA aircraft with a filed
// flight plan that adsbdb has no scheduled-flight-number record for at all.
function findFr24Match(callsign) {
  if (!fr24 || fr24.error || typeof fr24 !== 'object') return null;
  for (const info of Object.values(fr24)) {
    if (!Array.isArray(info)) continue; // skip "full_count"/"version"/"stats" keys
    if (info[16] === callsign) {
      return {
        from: info[11] || null,
        to: info[12] || null,
        // Field 18 is the operator's ICAO airline designator (SIA, QTR, ASY) --
        // the code actually filed in the ATC callsign, and unique per operator,
        // unlike IATA codes, which get reassigned. Empty for private/GA.
        airlineIcao: info[18] ? String(info[18]).toLowerCase() : null,
      };
    }
  }
  return null;
}

const adsbdbOk = !(resp && resp.error);
const route = adsbdbOk && resp && resp.response && resp.response.flightroute;

// No live FR24 entry for this callsign. Fall back to trusting adsbdb's route only if
// the aircraft is currently within a plausible distance of one of its claimed airports.
const PLAUSIBLE_RADIUS_KM = 150;
function adsbdbPlausible() {
  if (!route || !route.origin || !route.destination) return false;
  if (typeof nearest.lat !== 'number' || typeof nearest.lon !== 'number') return true;
  const dOrigin = distanceKm(nearest.lat, nearest.lon, route.origin.latitude, route.origin.longitude);
  const dDest = distanceKm(nearest.lat, nearest.lon, route.destination.latitude, route.destination.longitude);
  return dOrigin <= PLAUSIBLE_RADIUS_KM || dDest <= PLAUSIBLE_RADIUS_KM;
}

const adsbdbRoute = route && route.origin && route.destination
  ? { from: route.origin.iata_code || route.origin.icao_code, to: route.destination.iata_code || route.destination.icao_code }
  : null;
const adsbdbAirlineIata = route && route.airline && route.airline.iata ? route.airline.iata.toLowerCase() : null;
const adsbdbAirlineIcao = route && route.airline && route.airline.icao ? route.airline.icao.toLowerCase() : null;
const callsignIata = route && route.callsign_iata ? route.callsign_iata : null;

const fr24Match = findFr24Match(nearest.callsign);
const fr24Route = fr24Match && fr24Match.from && fr24Match.to ? { from: fr24Match.from, to: fr24Match.to } : null;

let match = null;
if (adsbdbRoute && fr24Route) {
  match = adsbdbRoute.from === fr24Route.from && adsbdbRoute.to === fr24Route.to;
}

// Trust order: a live FR24 match first (real current trajectory) beats adsbdb's route
// unconditionally; otherwise adsbdb's route only if it's geographically plausible given
// where the aircraft actually is right now. adsbdb having nothing at all (private jets,
// unknown callsigns, network errors) no longer blanks the whole cycle by itself -- FR24
// alone is enough to show a route/callsign, and vice versa.
let trustedRoute = null;
let trustedSource = 'none';
if (fr24Route) {
  trustedRoute = fr24Route;
  trustedSource = 'fr24';
} else if (adsbdbRoute && adsbdbPlausible()) {
  trustedRoute = adsbdbRoute;
  trustedSource = 'adsbdb-plausible';
}

// Airline identity for icons: the ICAO designator, from FR24's live feed first (same
// trust order as the route), else adsbdb's airline record. airlineIata is only ever
// adsbdb's own IATA field -- never derived from a flight number or callsign. Both
// null for a private/GA aircraft, which resolves to the generic icon downstream.
const airlineIcao = (fr24Match && fr24Match.airlineIcao) || adsbdbAirlineIcao;
const airlineIata = adsbdbAirlineIata;

// Nothing usable from either source -- skip this push cycle so the clock keeps
// showing its last good entry instead of a bare, unconfirmed callsign.
const skip = !adsbdbOk && !fr24Match;

// This full comparison stays on the item (visible in the n8n execution log for every
// run) even though only trustedRoute/airlineIata get used downstream -- so a bad
// adsbdb record, or a case where only one source had data, is obvious at a glance.
return [{
  json: {
    skip,
    callsign: nearest.callsign,
    callsignIata,
    airlineIcao,
    airlineIata,
    adsbdbOk,
    adsbdb: adsbdbRoute,
    fr24: fr24Route,
    match,
    trustedRoute,
    trustedSource
  }
}];
